int count_anchor(char *text, char mark) {
    int count = 0;

    while (*text) {
        if (*text == mark || *text == '\t')
            count++;
        text++;
    }

    return count;
}

int kind_buffer(char c) {
    if (c >= '0' && c <= '9')
        return 1;
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
        return 2;
    switch (c) {
    case ' ':
    case '\t':
    case '\n':
        return 3;
    case '\\':
        return 4;
    }

    return 1;
}

int copy_cursor(int shift) {
    char source[] = "the quick brown fox";
    char target[24];
    int n = 0;

    for (int i = 0; source[i]; i++) {
        char c = source[i];

        if (c != ' ') {
            int upper = c - 'a' + 'A' + shift;

            target[n++] = upper;
        }
    }
    target[n] = '\0';

    return n + target[2] - 'A';
}

